H("620.d.4.B",3,"Software that stores client contact details, appointments and service history is a:","client management system",["calculator","camera","hair dryer"],"It keeps records in one place.")
H("620.d.4.B",4,"When selecting a client management system, a salon should consider:","ease of use and features needed",["only the color of the logo","only the price of coffee","only the owner's pet"],"Choose what fits operations.")
H("620.d.4.C",3,"Recording formulas used and how the client felt about the result creates:","documentation",["rumors","delays","errors"],"Records help repeat or adjust services.")
H("620.d.4.C",4,"Why document client satisfaction after each service?","to improve future visits",["to avoid payment","to gossip","to fill time"],"Feedback guides future consultation.")
H("620.d.5.A",3,"A stylist demonstrates a forty-five degree haircut. This is an example of a:","basic haircut technique",["chemical service","manicure","color formula"],"Haircuts use set angles.")
H("620.d.5.A",4,"The angle at which hair is lifted from the head before cutting is the:","elevation",["texture","porosity","shade"],"Elevation affects shape and layering.")
H("620.d.5.B",3,"Filing, shaping and polishing the nails is part of a:","manicure",["pedicure only","shampoo","relaxer"],"A manicure treats hands and nails.")
H("620.d.5.B",4,"Before applying polish in a manicure, the nails should be:","cleaned and shaped",["left dirty","soaked in dye","oiled heavily"],"Preparation ensures good polish application.")
H("620.d.5.C",3,"Cleansing, steaming and applying a mask to the face is part of a basic:","facial service",["manicure","haircut","blow dry"],"Facials care for the skin.")
H("620.d.5.C",4,"In a facial, cleansing the skin before treatment removes:","dirt and makeup",["all moisture","natural oils entirely","skin cells permanently"],"A clean base is needed.")
H("620.d.5.D",3,"Applying relaxer, hair color or lightener are examples of:","chemical services",["manicure steps","haircut angles","blow-dry tools"],"Chemicals change hair structure or color.")
H("620.d.5.D",4,"Before most chemical services, a stylist should perform a:","strand test or patch test",["haircut only","manicure","blow dry only"],"Tests check for allergic reactions or damage.")
H("620.d.5.E",3,"Wetting, lathering and rinsing a client's hair is a basic:","shampooing technique",["permanent wave","thermal style","facial step"],"Shampooing cleans hair and scalp.")
H("620.d.5.E",4,"While shampooing, the stylist uses the pads of the fingers rather than the nails to protect the:","scalp",["floor","sink","towel"],"Nails can scratch the scalp.")
H("620.d.5.F",3,"Wrapping hair around rods and applying a solution to create lasting curls is a:","permanent wave",["blow dry","shampoo","manicure"],"Permanent waves change hair shape.")
H("620.d.5.F",4,"The step in a permanent wave that rebuilds the hair's bonds in its new shape is the:","neutralizer",["conditioner only","clarifier","toner"],"Neutralizer sets the curl.")
H("620.d.5.G",3,"Forming temporary curls with a curling iron is a basic:","curling technique",["perming step","manicure step","shampoo step"],"Heat curls last until washed.")
H("620.d.5.G",4,"To avoid burning the client, a stylist should check the iron's:","temperature",["color","brand","price"],"Heat settings affect safety.")
H("620.d.5.H",3,"Using a dryer, a brush and a nozzle to shape hair is basic:","blow drying",["perming","relaxing","dyeing"],"Blow drying shapes hair.")
H("620.d.5.H",4,"Pointing the dryer nozzle down the hair shaft helps close the cuticle and add:","smoothness and shine",["frizz","dryness","damage"],"Direction of airflow matters.")
H("620.d.5.I",3,"Flat irons and curling irons use heat to style hair. This category is:","thermal styling",["wet styling only","chemical styling","manual styling only"],"Thermal means heat.")
H("620.d.5.I",4,"A heat protectant spray is used before thermal styling to reduce:","hair damage",["hair growth","salon costs","wait times"],"It shields hair from high heat.")
# ---- 621 Cosmetology II ----
H("621.d.1.A",3,"A stylist who explains how the nervous system affects scalp massage is defending the importance of:","anatomy and physiology",["travel","sports","music"],"Body knowledge supports safe services.")
H("621.d.1.A",4,"Why does cosmetology require study of the body's systems?","services directly affect skin, hair and nails",["it reduces the need for tools","it replaces licensing","it avoids client contact"],"Understanding the body prevents harm.")
H("621.d.1.B",3,"The part of the hair that is visible above the scalp is the:","hair shaft",["hair root","follicle","papilla"],"The shaft is the visible part.")
H("621.d.1.B",4,"The nail's growth comes from cells in the:","matrix",["free edge","lunula tip only","cuticle fold edge"],"New nail cells form in the matrix.")
H("621.d.1.C",3,"Testing whether a mixture is acidic or alkaline applies the principles of:","chemistry",["geometry","geography","grammar"],"Chemistry explains product behavior.")
H("621.d.1.C",4,"A substance without carbon, like water or table salt, falls under:","inorganic chemistry",["organic chemistry","biology only","botany"],"Inorganic substances generally lack carbon-hydrogen chains.")
H("621.d.1.D",3,"Shaking a bottle of lotion before use is needed because it is a:","suspension or emulsion that can separate",["clear solution","pure element","solid bar"],"Separation requires remixing.")
H("621.d.1.D",4,"Sugar dissolved evenly in water forms a:","solution",["suspension","emulsion","precipitate"],"Solutes dissolve fully in a solvent.")
H("621.d.1.E",3,"A product with a pH close to that of healthy skin and hair is described as:","pH balanced",["harsh","untested","oily"],"Balanced products protect the skin and hair.")
H("621.d.1.E",4,"A high-alkaline hair product tends to cause the cuticle to:","swell and open",["close tightly","shrink","harden"],"Alkaline products raise the cuticle.")
H("621.d.1.F",3,"Acrylic nails form when a liquid monomer and powder polymer combine to create:","a hard bonded coating",["a loose powder","a thin water","a soap film"],"They polymerize into a hard layer.")
H("621.d.1.F",4,"A UV or LED lamp is used to harden:","gel nail enhancements",["nail clippers","hair color","shampoo"],"Gel products cure under light.")
H("621.d.1.G",3,"Before attaching hair extensions, the natural hair should be:","clean and free of buildup",["freshly oiled","coated in wax","left dirty"],"Clean hair improves attachment.")
H("621.d.1.G",4,"Careful removal of extensions helps prevent:","damage to the client's natural hair",["longer hair","faster growth","higher pH"],"Improper removal can break or pull hair.")
H("621.d.1.H",3,"A written plan for cleaning, disinfecting and handling blood exposure is an infection:","control plan",["menu","fashion line","sale flyer"],"Plans keep everyone safe.")
H("621.d.1.H",4,"Which belongs in a salon infection control plan?","cleaning schedules and disposal steps",["music playlists","coupon codes","client gossip"],"Plans list procedures and responsibilities.")
H("621.d.2.A",3,"Applying health and safety policies means doing what the posted rules say:","every day",["sometimes","rarely","never"],"Consistency protects clients.")
H("621.d.2.A",4,"A stylist who skips hand washing between clients is failing to apply:","health and safety procedures",["fashion trends","pricing rules","music licensing"],"Hygiene prevents cross-contamination.")
H("621.d.2.B",3,"Under TDLR rules, a spill of chemicals on the floor is a potentially:","hazardous situation",["profitable situation","decorative item","quiet moment"],"Recognizing hazards prevents injury.")
H("621.d.2.B",4,"A stylist who notices an exposed outlet near the shampoo bowl should:","report it and keep clients away",["ignore it","use it anyway","cover it with a towel"],"Water and electric hazards must be fixed.")
H("621.d.2.C",3,"To see exam eligibility and logged student hours, go to the:","TDLR website",["school gym","lost-and-found","bus stop"],"TDLR tracks that information.")
H("621.d.2.C",4,"Which information can a student find on the TDLR site?","exam results",["lunch recipes","game scores","coupon deals"],"Results and hours are posted there.")
H("621.d.2.D",3,"A license must be renewed on schedule by the:","licensee",["customer","vendor","landlord"],"The license holder is responsible.")
H("621.d.2.D",4,"Letting a license expire before renewing can result in:","not being allowed to legally work",["bonus pay","free supplies","more clients"],"An expired license stops legal practice.")
H("621.d.3.A",3,"Using shears with their blades closed when not in use and storing them safely shows:","safe tool use",["wasted time","slow service","poor posture"],"Careful handling prevents cuts.")
H("621.d.3.A",4,"Selecting the right tool for each service is part of employing tools:","safely and effectively",["randomly","carelessly","expensively"],"Right tool, right job.")
H("621.d.3.B",3,"A tilting, height-adjustable stool is an example of:","ergonomic equipment",["a risk","a hazard","a clutter source"],"It reduces strain.")
H("621.d.3.B",4,"Ergonomically designed equipment improves professional efficiency by reducing:","body strain",["client trust","service quality","income"],"Comfort supports performance.")
H("621.d.3.C",3,"A salon sends text reminders for appointments. This is using technology:","effectively",["wastefully","rarely","poorly"],"It improves attendance.")
H("621.d.3.C",4,"A good use of salon technology is to:","track appointments and sales",["distract staff","lose records","delay clients"],"Technology streamlines operations.")
H("621.d.3.D",3,"Used razors, chemical waste and nonhazardous trash must be separated, which applies universal:","precautions",["styles","prices","patterns"],"Different waste has different handling rules.")
H("621.d.3.D",4,"A stylist disposes of used hair color in the regular trash. This violates:","hazardous waste rules",["dress code","scheduling policy","parking rules"],"Chemicals need proper disposal.")
H("621.d.3.E",3,"Measuring the right amount of developer and color so the result is correct is formulating services based on the correct:","quality and quantity",["height","brand name","price tag"],"Correct amounts give predictable results.")
H("621.d.3.E",4,"Using too much of a chemical product can cause:","damage to hair or skin",["better results always","free refills","lower prices"],"Overuse is unsafe.")
H("621.d.4.A",3,"Evaluating what a client says she wants and what her hair can handle is:","appraising client desires",["ignoring input","guessing","gossiping"],"Appraisal ensures realistic goals.")
H("621.d.4.A",4,"A client wants platinum blonde from near-black hair in one visit. A good stylist will:","explain limits and propose a safe plan",["promise it happens","refuse to talk","skip the consult"],"Honest advice protects hair.")
H("621.d.4.B",3,"Recording the formula, products and the client's reaction helps a stylist judge:","client satisfaction",["the weather","the traffic","the lunch menu"],"Notes help refine services.")
H("621.d.4.B",4,"Why keep detailed service notes?","to repeat or adjust results next visit",["to hide errors","to fill paperwork","to delay checkout"],"Notes support consistent service.")
H("621.d.4.C",3,"Training materials and free product samples offered by a supplier are examples of vendor:","resources",["rumors","debts","penalties"],"Vendors can support training.")
H("621.d.4.C",4,"A benefit of building relationships with vendors is access to:","product education and support",["no tools","more rules","unrelated ads"],"Vendors share knowledge.")
H("621.d.4.D",3,"Mastering haircuts at zero, forty-five and ninety degrees shows ability in basic:","cutting techniques",["perming only","manicures","facials"],"Angles produce different shapes.")
H("621.d.4.D",4,"Cutting with higher elevation generally produces more:","layering",["weight","blunt lines","length"],"Elevation creates graduated lengths.")
H("621.d.4.E",3,"Completing a manicure and a facial on a model demonstrates:","service proficiency",["lack of skill","carelessness","indifference"],"Practice shows mastery.")
H("621.d.4.E",4,"A mock chemical service lets a student practice without risk to a:","real client's hair",["salon sink","hair dryer","mirror"],"Mock services build skill safely.")
H("621.d.4.F",3,"Shampooing, perming, curling, blow drying and thermal styling are all part of:","basic cosmetology services",["accounting","landscaping","plumbing"],"These are core services.")
H("621.d.4.F",4,"Mastering a technique means performing it with accuracy and:","consistency",["delay","error","doubt"],"Mastery shows reliable results.")
H("621.d.5.A",3,"Posting before-and-after photos online and creating short videos are ways to use:","multimedia marketing",["silent ads","blank flyers","hidden signs"],"Multimedia attracts clients.")
H("621.d.5.A",4,"Which is a marketing technique a salon can use to attract customers?","social media posts of finished work",["hiding the address","refusing walk-ins","closing early"],"Showcasing work builds interest.")
H("621.d.5.B",3,"A list of services with prices and descriptions is a salon's:","service menu",["lunch menu","loan","payroll"],"Menus show what is offered.")
H("621.d.5.B",4,"A salon updates its service menu to add popular new treatments. This follows:","industry trends",["last year's weather","random guesses","personal luck"],"Menus should reflect demand.")
H("621.d.5.C",3,"Surveys, comment cards and online reviews are ways to collect client:","feedback",["debts","fees","gifts"],"Feedback shows how clients feel.")
H("621.d.5.C",4,"Reading client feedback helps a salon understand customer:","needs and preferences",["birthdays only","pet names","vehicle types"],"It guides service improvements.")
H("621.d.5.D",3,"A portfolio with certifications, resume and work samples shows a stylist's:","qualifications",["secrets","hobbies","chores"],"A portfolio supports hiring.")
H("621.d.5.D",4,"Photos of completed haircuts and licenses are examples of items for an employment:","portfolio",["poster","menu","receipt"],"Portfolio content proves ability.")
H("621.d.5.E",3,"Groups that provide training, networking and standards for cosmetologists are:","professional organizations",["competitors only","random clubs","tax offices"],"Organizations support the field.")
H("621.d.5.E",4,"One advantage of joining a professional organization is:","access to continuing education",["lower license fees automatically","no renewal needed","fewer client visits"],"Organizations offer learning and networking.")
# ---- 622 Practicum in Cosmetology II ----
H("622.d.1.A",3,"Choosing a neat, clean uniform for a salon shift shows:","professionalism",["rebellion","hurry","apathy"],"Attire reflects professionalism.")
H("622.d.1.A",4,"Which attire best fits a professional cosmetology practicum?","clean clothing that meets salon standards",["worn-out clothes","costume pieces","sleepwear"],"Standards protect safety and image.")
H("622.d.1.B",3,"Writing a polite follow-up email to a client and speaking clearly in person is practicing:","oral and written communication",["silence","guessing","rushing"],"Clear communication builds trust.")
H("622.d.1.B",4,"Which is an example of professional written communication in a salon?","a courteous appointment confirmation",["a slang-filled text","a joke meme","an angry note"],"Written messages should be polite.")
H("622.d.1.C",3,"A stylist who takes responsibility for the quality of her haircuts shows personal:","ownership",["blame","doubt","luck"],"Accountability is key.")
H("622.d.1.C",4,"When a mistake happens, an employee with ownership will:","fix it and learn from it",["hide it","blame a coworker","ignore the client"],"Owning mistakes builds trust.")
H("622.d.1.D",3,"Opening a mobile hair-styling business is an example of exploring:","entrepreneurship",["retirement","unemployment","tourism"],"Entrepreneurs start businesses.")
H("622.d.1.D",4,"Besides being an employee, a licensed cosmetologist could:","open a salon",["avoid clients","skip renewal","stop working"],"Business ownership is an option.")
H("622.d.1.E",3,"Collecting your best work samples and evaluations into a folder prepares you to build a:","portfolio",["trash bin","playlist","score sheet"],"Portfolios show mastery.")
H("622.d.1.E",4,"A mastery-level portfolio for a job search should include:","evaluations and samples of finished work",["receipts only","unrelated drawings","blank pages"],"Evidence of skill helps employers.")
H("622.d.2.A",3,"Following health and safety policies in a real work setting protects:","clients and employees",["only managers","only customers","only owners"],"Safety is everyone's job.")
H("622.d.2.A",4,"The best way to apply workplace safety knowledge is to:","follow procedures every time",["follow them when watched","skip them when busy","ask others to do it"],"Consistency prevents incidents.")
H("622.d.2.B",3,"Cleaning combs, brushes and stations with an approved product is part of:","disinfecting the work area",["decorating","advertising","hiring"],"Disinfection stops germs.")
H("622.d.2.B",4,"Which should happen between clients?","tools and surfaces are cleaned and disinfected",["tools are shared as is","stations are left dirty","towels are reused unwashed"],"Prevents cross-contamination.")
H("622.d.2.C",3,"Keeping floors clear and storing chemicals properly are techniques to avoid:","risks and hazards",["profit","clients","orders"],"Prevention is safer.")
