H("622.d.2.D",3,"Hazardous materials such as used dye must be thrown away using industry:","best practices",["shortcuts","guesses","habits of choice"],"Proper disposal protects people.")
H("622.d.2.D",4,"Hazardous waste disposal rules in a salon are intended to protect staff, clients and the:","environment",["menu","marketing plan","dress code"],"Waste must be handled safely.")
H("622.d.3.A",3,"Using shears, irons and clippers with more speed and still staying safe shows increased:","fluency",["fear","delay","doubt"],"Fluency means skill with ease.")
H("622.d.3.A",4,"A stylist who cuts accurately and handles tools safely without prompting shows:","proficiency",["inexperience","reluctance","risk"],"Proficiency comes with practice.")
H("622.d.3.B",3,"Using ergonomic equipment confidently shows professional:","efficiency",["fatigue","delay","waste"],"Efficiency saves energy.")
H("622.d.3.B",4,"Which habit shows increased fluency with ergonomics?","adjusting chair and posture before each service",["slouching at stations","ignoring posture","working in awkward angles"],"Good habits protect the body.")
H("622.d.3.C",3,"Booking systems, card readers and social media are technology sources that a salon can:","integrate",["fear","avoid","destroy"],"Integration saves time.")
H("622.d.3.C",4,"A stylist who uses digital tools to keep client notes shows effective use of:","technology in the salon",["old ledgers only","paper guesses","verbal memory only"],"Digital tools improve accuracy.")
H("622.d.4.A",3,"A client says her color came out too dark. A stylist with little guidance should use a consultation to:","resolve the concern",["ignore it","argue","hide"],"Good consultation solves issues.")
