H("622.d.4.C",4,"Client satisfaction records may come from a simulated or an actual:","work situation",["vacation","party","lecture"],"Both settings build skill.")
H("622.d.4.D",3,"A list of brands and formulas used on a client informs her next:","consultation",["bill only","parking","cleanup"],"Product history guides decisions.")
H("622.d.4.D",4,"Documenting products used helps a stylist avoid repeating a product that caused:","an allergic reaction",["a compliment","a tip","a smile"],"Past reactions guide choices.")
H("622.d.4.E",3,"A program that tracks appointments, payments and client history is a:","client management system",["calculator","timer","scale"],"It organizes the business.")
H("622.d.4.E",4,"Using a client management system in different work settings shows:","adaptability",["confusion","avoidance","disorder"],"Flexible skill with tools is valued.")
H("622.d.5.A",3,"Performing a precise haircut with clean lines shows mastery-level:","skills and technique",["guesswork","luck","rushing"],"Mastery is accurate and consistent.")
H("622.d.5.A",4,"A mastery-level haircut is judged by its accuracy and:","consistency",["speed only","cost","color"],"Mastery means reliable quality.")
H("622.d.5.B",3,"Shaping nails evenly and applying polish smoothly demonstrates mastery-level:","manicure skills",["perm skills","haircut skills","shampoo skills"],"Nail care requires precision.")
H("622.d.5.B",4,"A professional manicure includes nail shaping, cuticle care and:","polish application",["haircutting","perming","blow drying"],"These are standard steps.")
H("622.d.5.C",3,"Cleansing, exfoliating and massaging the face are parts of a:","facial service",["manicure","haircut","blow dry"],"Facials care for the skin.")
H("622.d.5.C",4,"Skin analysis before a facial helps the stylist choose the right:","products and treatment",["hairstyle","nail shape","music"],"Analysis ensures safe treatment.")
H("622.d.5.D",3,"Knowing how relaxers, color and lighteners work shows mastery of:","chemical applications",["haircut angles","manicure tools","facial masks"],"Chemistry knowledge is essential.")
H("622.d.5.D",4,"A stylist who reads product directions, times the service and rinses properly shows:","mastery-level chemical knowledge",["careless work","guesswork","lack of training"],"Following directions prevents damage.")
H("622.d.5.E",3,"Using the right water temperature and gentle massage while washing hair shows mastery-level:","shampooing",["perming","coloring","curling"],"Shampoo technique affects comfort.")
H("622.d.5.E",4,"A mastery-level shampoo service avoids scratching the scalp by using:","the pads of the fingers",["fingernails","a stiff brush","a comb"],"Gentle contact protects the scalp.")
H("622.d.5.F",3,"Wrapping hair on rods, applying solution and neutralizing it correctly shows mastery-level:","permanent waving",["blow drying","shampooing","trimming"],"Waving has precise steps.")
H("622.d.5.F",4,"Choosing the correct rod size for a permanent wave determines the size of the:","curl",["comb","chair","bowl"],"Rod size shapes curl pattern.")
H("622.d.5.G",3,"Using hot irons to create smooth, uniform curls on a client shows mastery-level:","curling technique",["cutting technique","dyeing technique","filing technique"],"Curling needs control and timing.")
