H("622.d.5.H",3,"Smoothing hair with a round brush and dryer while controlling heat shows mastery-level:","blow drying",["perming","relaxing","bleaching"],"Blow drying needs coordination.")
H("622.d.5.H",4,"A stylist keeps the dryer moving to avoid burning the client's:","scalp and hair",["floor","chair","mirror"],"Constant movement prevents heat damage.")
H("622.d.5.I",3,"Using heated tools such as flat irons to style hair shows mastery-level:","thermal styling",["chemical styling","cold styling","wet-set styling"],"Thermal styling uses heat.")
H("622.d.5.I",4,"A stylist uses a heat protectant and the right temperature setting during thermal styling to prevent:","burn and breakage",["growth","volume","shine loss"],"Protecting hair is part of mastery.")
# ---- 665 Human Services: Practicum I ----
