H("665.d.1.E",4,"Social service agencies create jobs and also improve community:","well-being",["noise","traffic","crime"],"They have social and economic impact.")
H("665.d.1.F",3,"Groups like the National Association of Social Workers help professionals through:","standards and networking",["free vacations","tax cuts","gym access"],"Professional organizations provide support.")
H("665.d.1.F",4,"One reason a human services professional joins an association is to:","stay current on laws and best practices",["avoid training","skip ethics","reduce duties"],"Associations share updates.")
H("665.d.2.A",3,"A worker who nods, smiles and speaks kindly is using verbal and:","nonverbal communication",["silent treatment","gossip","one-word replies"],"Body language supports words.")
H("665.d.2.A",4,"Sending a clear, polite email to a client is an example of _____ communication.","electronic",["nonverbal","verbal only","telepathic"],"Email is electronic communication.")
H("665.d.2.B",3,"Showing a client that you understand how they feel is called:","empathy",["envy","apathy","vanity"],"Empathy builds trust.")
H("665.d.2.B",4,"Which response shows active listening to a worried client?","repeating key concerns and asking clarifying questions",["checking your phone","changing the subject","interrupting with advice"],"Active listening confirms understanding.")
H("665.d.2.C",3,"Greeting a customer, answering a question and completing a sale are part of:","customer service",["inventory","payroll","recycling"],"Service techniques finish transactions.")
H("665.d.2.C",4,"A customer is upset about a mix-up at the counter. The best first step is to:","listen calmly and apologize",["argue","walk away","blame a coworker"],"Calm response de-escalates.")
H("665.d.2.D",3,"Learning how much risk a client is comfortable with when planning services involves their risk:","tolerance",["profit","spending","logo"],"Clients differ in comfort with risk.")
H("665.d.2.D",4,"Finding out a client's available resources helps a worker recommend:","suitable options",["random choices","costly extras","unrelated products"],"Fit matters.")
