H("665.d.5.A",3,"A safe place to offer services should be easy to reach, well lit and:","free of hazards",["hidden","loud","cluttered"],"Safety first.")
H("665.d.5.A",4,"Which location is safest for a community help center?","a well-lit, accessible building",["a dark alley","a crowded construction site","an unmarked trailer"],"Accessibility and safety matter.")
H("665.d.5.B",3,"Needed desks, computers and electrical power are part of a functional:","work environment",["costume","menu","game"],"Environments must support the work.")
