H("665.d.5.C",3,"A non-threatening environment feels welcoming and:","safe",["scary","hostile","chaotic"],"Clients should feel comfortable.")
H("665.d.5.C",4,"Soft lighting, clear signs and friendly greeting help create a:","non-threatening workplace",["tense workplace","hidden workplace","noisy workplace"],"Environment affects client comfort.")
H("665.d.5.D",3,"Respect, patience and good manners are social skills needed to work with a:","diverse population",["single age group only","small family only","machine only"],"Clients come from many backgrounds.")
