H("665.d.6.A",3,"Working with teammates toward shared goals is:","collaboration",["competition","isolation","delay"],"Teams succeed together.")
H("665.d.6.A",4,"Which action best supports organizational goals?","completing your tasks and helping teammates",["working alone secretly","blocking others","ignoring deadlines"],"Cooperation advances goals.")
